"""autoedit engine picture renderer (generated by regen_engine.py from a production build.py).
Reads the compiled timeline.json + keys.json via timeline.py (no case-specific code).

render_shot(shot) -> iterator of RGB uint8 frames (1080, 1920, 3), exactly shot['nf'] frames.
render_range(shot, i0, i1) -> the same for shot-local frames [i0, i1).
still(t_seconds) -> one finished frame of the edit at time t.
Order per frame: source (cover / blurfill+crop) -> privacy blur (keys) -> grade (per-shot gamma)
-> push / camera -> devices (date, credit, safety, captions) -> dips / crossfade.
Audio is NOT here (other agent).
"""
import json, math, os, sys
import numpy as np
import cv2

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import kit  # noqa: E402
import timeline as TLM  # noqa: E402
import mapclip  # noqa: E402

P = TLM.P
FPS, W, H = kit.FPS, kit.W, kit.H
K = json.load(open(TLM.KEYS_PATH, encoding='utf8')) if os.path.exists(TLM.KEYS_PATH) else {}
BLUR = K.get('blur', {})
MAX_PUSH = 0.08                       # total push cap per shot (1.5 %/s on short shots)
GAMMA_FILE = os.environ.get('AUTOEDIT_GAMMA') or os.path.join(TLM.EDIT_DIR, 'gamma.json')
_SHOTS = None


def shots():
    global _SHOTS
    if _SHOTS is None: _SHOTS = TLM.timeline()
    return _SHOTS


def src_path(src): return os.path.join(P, 'sources', src + '.mp4')


# ---------------------------------------------------------------- privacy blur
def _interp_box(run, t):
    """run: [[t, x0, y0, x1, y1], ...] -> box at t (linear) or None outside the run."""
    if t < run[0][0] - 1e-6 or t > run[-1][0] + 1e-6: return None
    for r0, r1 in zip(run, run[1:]):
        if r0[0] <= t <= r1[0]:
            k = (t - r0[0]) / max(1e-6, r1[0] - r0[0])
            return [r0[j] + (r1[j] - r0[j]) * k for j in range(1, 5)]
    return list(run[-1][1:5])


def _mf_box(table, t):
    fno = t * FPS; fs = [r[0] for r in table]
    if fno < fs[0] - 0.5 or fno > fs[-1] + 0.5: return None
    cx, cy, w, h = [float(np.interp(fno, fs, [r[j] for r in table])) for j in range(1, 5)]
    return (cx - w / 2, cy - h / 2, cx + w / 2, cy + h / 2), max(6.0, h / 3)


def ellipse_box(z): cx, cy, rx, ry = z; return (cx - rx, cy - ry, cx + rx, cy + ry)


def blur_boxes(shot, src, t):
    """[(box, sigma)] for one source frame at src time t. keys.json blur.<SRC>:
    cabin_zones [[cx,cy,rx,ry]] (shots with cabin=true, + shot zones_extra; cabin_scale, cabin_sigma), runs [[[t,x0,y0,x1,y1],..]] (seconds,
    linear), tables [[[frame,cx,cy,w,h],..]] (30 fps frame numbers, sigma = h/3)."""
    out = []; B = BLUR.get(src or '', {}); k = B.get('cabin_scale', 1.0)
    if shot.get('cabin'):                       # cabin_scale trims zones; cabin_sigma 'cap' = glare-capped blur
        out += [(ellipse_box((z[0], z[1], z[2] * k, z[3] * k)), B.get('cabin_sigma'))
                for z in B.get('cabin_zones', []) + list(shot.get('zones_extra') or [])]
    for run in B.get('runs', []):
        b = _interp_box(run, t)
        if b: out.append((b, None))
    for tab in B.get('tables', []):
        r = _mf_box(tab, t)
        if r: out.append(r)
    return out


def wants_haar(shot):
    """Inline face blur: flagged shots + every shot of a source past its keys.json blur.<SRC>.haar_from (s)."""
    hf = BLUR.get(shot.get('src') or '', {}).get('haar_from')
    if shot.get('haar'): return True
    if hf is None or shot['kind'] not in ('ff', 'still'): return False
    return (shot.get('a') if shot['kind'] == 'ff' else still_t(shot)) >= hf


def has_blur(shot):
    """Constant per shot (no flicker of the safety note): any blur over the shot's source range."""
    if shot.get('cabin') or wants_haar(shot): return True
    src = shot.get('src')
    if shot['kind'] == 'still':
        return bool(blur_boxes(shot, src, still_t(shot)))
    if shot['kind'] != 'ff': return False
    t0, t1 = shot['a'], shot['a'] + shot['nf'] * shot['speed'] / FPS
    return any(blur_boxes(shot, src, t) for t in np.arange(t0, t1, 0.1))


_CASC = None


def haar_faces(a):
    global _CASC
    if _CASC is None:
        d = cv2.data.haarcascades
        _CASC = [cv2.CascadeClassifier(d + 'haarcascade_frontalface_default.xml'),
                 cv2.CascadeClassifier(d + 'haarcascade_profileface.xml')]
    sm = cv2.resize(np.asarray(a, np.uint8), (960, 540))
    g = cv2.cvtColor(sm, cv2.COLOR_RGB2GRAY)
    ycc = cv2.cvtColor(sm, cv2.COLOR_RGB2YCrCb)
    skin = ((ycc[..., 1] >= 135) & (ycc[..., 1] <= 180) & (ycc[..., 2] >= 85) & (ycc[..., 2] <= 135)
            & (ycc[..., 0] >= 40)).astype(np.float32)
    out = []
    for c in _CASC:
        for flip in (False, True) if c is _CASC[1] else (False,):
            gg = cv2.flip(g, 1) if flip else g
            for x, y, w, h in c.detectMultiScale(gg, 1.1, 6, minSize=(14, 14), maxSize=(90, 90)):
                if flip: x = 960 - x - w
                # B7 false-hit filter: no boxes in the sky band / road-hood band, sane size, real skin in the core
                if y + h / 2 < 540 * 0.18 or y + h / 2 > 540 * 0.86: continue
                if not 14 <= w <= 90 or not 0.7 <= w / max(1, h) <= 1.4: continue
                core = skin[int(y + h * 0.25):int(y + h * 0.8), int(x + w * 0.2):int(x + w * 0.8)]
                if core.size == 0 or core.mean() < 0.22: continue
                cx, cy, s = (x + w / 2) * 2, (y + h * 0.42) * 2, max(w, h) * 2 * 1.35   # face + hair, not 3.6x
                out.append((cx - s / 2, cy - s * 0.58, cx + s / 2, cy + s * 0.48))
    return out


def apply_blur(a, boxes):
    a = a.astype(np.float32)
    for b, sg in boxes:
        if sg == 'cap':
            x0, y0, x1, y1 = [int(round(v)) for v in b]
            x0, y0 = max(0, x0), max(0, y0)
            reg = a[y0:max(y0, y1), x0:max(x0, x1)]
            if reg.size: np.minimum(reg, np.percentile(reg, 60) + 25, out=reg)
            sg = None
        a = kit.soft_blur(a, b, sigma=sg)
    return a


# ---------------------------------------------------------------- sources
def still_t(shot):
    if shot.get('fz'): return K['stills'][shot['fz']] / FPS
    return shot['t']


def _read(shot, t, n=1):
    return kit.read_frames(src_path(shot['src']), max(0.0, t), n / FPS, shot.get('mode', 'cover'), crop=shot.get('crop'))


def _src_index(shot, i):
    """shot-local frame -> source frame index k (30 fps from shot['a'])."""
    j = max(0, i - shot.get('head', 0))
    k = int(math.floor(j * shot['speed'] + 1e-6))
    lim = shot.get('tail_lim')
    if lim is not None: k = min(k, max(0, int(math.floor((lim - shot['a']) * FPS)) - 1))
    return k


_GAMMA = None


def gamma_for(shot):
    global _GAMMA
    if _GAMMA is None:
        _GAMMA = json.load(open(GAMMA_FILE)) if os.path.exists(GAMMA_FILE) else {}
    key = f"{shot['name']}|{shot.get('src')}|{shot.get('a') if shot['kind'] == 'ff' else still_t(shot)}|{shot['nf']}"
    if key not in _GAMMA:
        if shot['kind'] == 'still':
            ts = [still_t(shot)]
        else:
            k1 = _src_index(shot, shot['nf'] - 1)
            ts = [shot['a'] + k1 * q / 4 / FPS for q in range(5)]
        fr = [next(iter(_read(shot, t))) for t in ts]
        _GAMMA[key] = round(kit.shot_gamma(fr), 4)
        try: json.dump(_GAMMA, open(GAMMA_FILE, 'w'), indent=0)
        except OSError: pass
    return _GAMMA[key]


def _push_rate(shot):
    r = shot.get('push', 0.015) or 0.0
    return min(r, MAX_PUSH / max(0.1, shot['nf'] / FPS))


# ---------------------------------------------------------------- per-kind cores (no fades)
def _devices(shot, a, i):
    if shot.get('date'): a = kit.typed_date(a, i - shot.get('pre', 0), shot['date'])
    if shot.get('_safety'): a = kit.safety_note(a)
    if shot.get('credit'): a = kit.source_credit(a, shot['credit'])
    for f0, f1, text, y in shot.get('captions', []):
        if f0 <= i < f1: a = kit.caption(a, text, y=y)
    return a


def _core_ff(shot, i0, i1):
    g = gamma_for(shot); rate = _push_rate(shot)
    k0, k1 = _src_index(shot, i0), _src_index(shot, max(i0, i1 - 1))
    stream = _read(shot, shot['a'] + k0 / FPS, k1 - k0 + 1)
    cur_k, cur = k0 - 1, None
    faces, face_hold = [], 0
    for i in range(i0, i1):
        k = _src_index(shot, i)
        while cur_k < k:
            cur = next(stream); cur_k += 1
            t = shot['a'] + cur_k / FPS
            boxes = blur_boxes(shot, shot['src'], t)
            if wants_haar(shot):
                det = haar_faces(cur)
                if det: faces, face_hold = det, 10
                elif face_hold > 0: face_hold -= 1
                else: faces = []
                boxes += [(b, None) for b in faces]
            src_frame = apply_blur(cur, boxes) if boxes else cur
            graded = _look(shot, src_frame, g)
        if shot.get('s', 1.0) != 1.0:                                   # B7: punch-in / tight crop on ff shots
            a = kit.camera(graded, shot['s'], shot.get('cx', 0.5), shot.get('cy', 0.5))
            a = kit.push(a, i, shot['nf'], rate=rate)
        else:
            a = kit.push(graded, i, shot['nf'], rate=rate)
        yield _devices(shot, a, i)


def _look(shot, fr, g):
    """Grade one source frame. B7: MF (saturated blue sky) muted hard toward Abyssal: sky highlights pulled,
    sat 0.30, cooler/darker; optional 'tint' = 'bw' (one cool B&W beat per case)."""
    if (TLM.SRC_MODE.get(shot.get('src')) or {}).get('look') != 'sky_mute':   # per-source look (video.json sources)
        return kit.grade(fr, gamma=g)
    f = np.asarray(fr, np.float32)
    L = f.mean(2)
    sky = np.clip((L - 120) / 90, 0, 1) * np.clip((f[..., 2] - f[..., 0] - 10) / 40, 0, 1)
    sky = np.maximum(sky, np.clip((L - 200) / 40, 0, 1) * 0.6)          # white clouds too
    sky = cv2.GaussianBlur(sky, (0, 0), 3)[..., None]
    f = f * (1 - 0.30 * sky)
    gm = f.mean(2, keepdims=True); f = gm + (f - gm) * 0.55             # pre-desat the electric blue
    if shot.get('tint'):                                                # one sepia / B&W beat (kit.grade tint)
        return kit.grade(f, tint=shot['tint'], sat=0.30, gamma=(g or 1.0) * 1.05)
    out = kit.grade(f, sat=0.30, gamma=(g or 1.0) * 1.12)
    return np.asarray(out, np.float32) * np.float32((0.93, 0.96, 1.0))


def _core_still(shot, i0, i1):
    t = still_t(shot)
    fr = next(iter(_read(shot, t)))
    boxes = blur_boxes(shot, shot['src'], t)
    if boxes: fr = apply_blur(fr, boxes)
    graded = _look(shot, fr, gamma_for(shot))
    nf = shot['nf']; s0 = shot.get('s', 1.0); s1 = shot.get('s_end')
    dx, dy = shot.get('drift', (0.0, 0.0))
    rate = 0.0 if s1 else _push_rate(shot)
    for i in range(i0, i1):
        e = kit.sine_io(i / max(1, nf - 1))
        s = (s0 + (s1 - s0) * e) if s1 else s0 * (1 + rate * (nf / FPS) * e)
        a = kit.camera(graded, s, shot.get('cx', 0.5), shot.get('cy', 0.5), dx * W * e, dy * H * e)
        yield _devices(shot, a, i)


def _plate(spec):
    sh = dict(spec, kind='still', mode=TLM.SRC_MODE[spec['src']]['mode'], crop=TLM.SRC_MODE[spec['src']]['crop'])
    t = still_t(sh); fr = next(iter(_read(sh, t)))
    boxes = blur_boxes(sh, sh['src'], t)
    return kit.title_plate(apply_blur(fr, boxes) if boxes else fr.astype(np.float32))


_PAGES = {}


def _page(name):
    if name not in _PAGES:
        p = os.path.join(P, 'assets', 'pages', f'{name}_page.png')
        im = cv2.cvtColor(cv2.imread(p), cv2.COLOR_BGR2RGB)
        sc = im.shape[1] / K['pages'][name]['size'][0]
        _PAGES[name] = (im, sc)
    return _PAGES[name]


def _map_tiles(shot, i0, i1):
    """Map frames from cached EOX tiles (kit.map_eox); assets/make_maps_pc.py renders the PC map clips with this."""
    tiles = os.path.join(P, shot['tiles'])
    for i in range(i0, i1):
        yield kit.map_eox(i, shot['nf'], tiles, shot['lat'], shot['lon'], shot['label'], zooms=shot.get('zooms', (10, 14)))


def _core_other(shot, i0, i1):
    kind, nf = shot['kind'], shot['nf']
    pre = shot.get('pre', 0)
    if kind == 'card':
        plate = _plate(shot['plate'])
        for i in range(i0, i1): yield kit.title_card(i, nf, shot['num'], shot['title'], plate=plate)
    elif kind == 'list':
        plate = _plate(shot['plate'])
        for i in range(i0, i1): yield kit.case_list(i, nf, shot['names'], plate=plate)
    elif kind == 'map':                                                  # PC clip (make_maps_pc.py) else tiles
        clip = mapclip.clip_path(P, shot)
        if os.path.exists(clip) and not os.environ.get('AUTOEDIT_MAP_TILES'): yield from mapclip.read(clip, i0, i1)
        else: yield from _map_tiles(shot, i0, i1)
    elif kind == 'page':
        im, sc = _page(shot['page'])
        if shot['hl'] is None: lines, start = shot['box'], 10 ** 6       # push only, no marker
        else: lines, start = K['pages'][shot['page']]['hl'][shot['hl']]['lines'], 48
        lines = [[v * sc for v in b] for b in lines]
        for i in range(i0, i1): yield kit.page_highlight(im, i - pre, nf - pre, lines, start=start)
    elif kind == 'end':
        prev = shots()[shot['idx'] - 1]
        last = next(_core(prev, prev['nf'] - 1, prev['nf']))
        for i in range(i0, i1): yield kit.end_hold(last, i, nf)
    else:
        raise ValueError(kind)


def _core(shot, i0, i1):
    if shot['kind'] in ('ff', 'still') and '_safety' not in shot: shot['_safety'] = has_blur(shot)
    if shot['kind'] == 'ff': return _core_ff(shot, i0, i1)
    if shot['kind'] == 'still': return _core_still(shot, i0, i1)
    return _core_other(shot, i0, i1)


# ---------------------------------------------------------------- public
def render_range(shot, i0, i1):
    nf = shot['nf']; xf = shot.get('xfade', 0) if shot['kind'] == 'ff' else 0
    prev = shots()[shot['idx'] - 1] if xf and shot['idx'] > 0 else None
    pstream = _core(prev, prev['nf'] + i0, prev['nf'] + min(xf, i1)) if prev and i0 < xf else None
    for i, a in zip(range(i0, i1), _core(shot, i0, i1)):
        a = np.asarray(a, np.float32)
        if pstream is not None and i < xf:
            a = kit.crossfade(next(pstream), a, (i + 1) / (xf + 1))
        if shot.get('fade_in') and i < shot['fade_in']:
            a = kit.dip(a, i, nf, up=shot['fade_in'], mode='in')
        if shot.get('fade_out') and i >= nf - shot['fade_out']:
            a = kit.dip(a, i, nf, down=shot['fade_out'], mode='out')
        yield kit.u8(a)


def render_shot(shot):
    return render_range(shot, 0, shot['nf'])


render_frames = render_shot   # name used by farm_entry (B3 handoff)


def shot_at(f):
    for s in shots():
        if s['f0'] <= f < s['f0'] + s['nf']: return s
    return shots()[-1]


def still(t_seconds):
    f = int(round(t_seconds * FPS)); s = shot_at(f); i = min(s['nf'] - 1, f - s['f0'])
    return next(render_range(s, i, i + 1))


# ---------------------------------------------------------------- QA contact sheet (light, laptop OK)
def contact_all(out=None, tw=384, cols=8):
    from PIL import Image, ImageDraw
    S = shots(); th = tw * H // W; lab = 22
    rows = math.ceil(len(S) / cols)
    sheet = Image.new('RGB', (cols * tw, rows * (th + lab)), (20, 20, 20))
    d = ImageDraw.Draw(sheet)
    for n, s in enumerate(S):
        i = s['nf'] // 2; f = s['f0'] + i
        fr = next(render_range(s, i, i + 1))
        tile = Image.fromarray(cv2.resize(fr, (tw, th), interpolation=cv2.INTER_AREA))
        x, y = (n % cols) * tw, (n // cols) * (th + lab)
        sheet.paste(tile, (x, y + lab))
        t = f / FPS
        d.text((x + 4, y + 4), f'{int(t // 60)}:{t % 60:05.2f} {s["name"]} {s["kind"]} {s.get("src") or ""}', fill=(240, 240, 240))
        print(f'{n:3d} {s["name"]}', flush=True)
    out = out or os.path.join(TLM.EDIT_DIR, 'qa', 'CONTACT_all.jpg')
    os.makedirs(os.path.dirname(out), exist_ok=True)
    sheet.save(out, quality=85)
    sheet.resize((sheet.width // 2, sheet.height // 2)).save(out.replace('.jpg', '_half.jpg'), quality=80)
    return out


if __name__ == '__main__':
    if 'contact' in sys.argv: print(contact_all())
